def transform(grid):
    h, w = len(grid), len(grid[0])

    # The divider is the full row or column of color 2.
    div_rows = [r for r in range(h) if all(v == 2 for v in grid[r])]
    div_cols = [c for c in range(w) if all(grid[r][c] == 2 for r in range(h))]

    # Background is the most frequent color.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    obj = [(r, c) for r in range(h) for c in range(w)
           if grid[r][c] not in (background, 2)]
    out = [row[:] for row in grid]
    if not obj:
        return out

    if div_cols:
        dc = div_cols[0]
        minc = min(c for r, c in obj)
        maxc = max(c for r, c in obj)
        shift = (dc - 1 - maxc) if dc > maxc else (dc + 1 - minc)
        moved = [(r, c + shift, grid[r][c]) for r, c in obj]
        for r, c in obj:
            out[r][c] = background
        for r, c, color in moved:
            out[r][c] = color
        edge = min(c for r, c, color in moved) - 1 if dc > maxc else max(c for r, c, color in moved) + 1
        if 0 <= edge < w:
            for r in range(h):
                out[r][edge] = 8
    elif div_rows:
        dr = div_rows[0]
        minr = min(r for r, c in obj)
        maxr = max(r for r, c in obj)
        shift = (dr - 1 - maxr) if dr > maxr else (dr + 1 - minr)
        moved = [(r + shift, c, grid[r][c]) for r, c in obj]
        for r, c in obj:
            out[r][c] = background
        for r, c, color in moved:
            out[r][c] = color
        edge = min(r for r, c, color in moved) - 1 if dr > maxr else max(r for r, c, color in moved) + 1
        if 0 <= edge < h:
            for c in range(w):
                out[edge][c] = 8

    return out
